(3002171, 422694, 15711, '<td valign="top">Great focus and DOF.  Love the eyes.</td>', 'Great focus and DOF.  Love the eyes.', '2006-11-05 15:02:44.000000', NULL, 1),
(3002174, 422582, 24454, '<td valign="top">Excellent focus!  Love the sepias!  I think this would be a perfect 10 if there was just a tad more consistent light on the top side of the face that''s lit -- but its still a great portrait!  8</td>', 'Excellent focus!  Love the sepias!  I think this would be a perfect 10 if there was just a tad more consistent light on the top side of the face that''s lit -- but its still a great portrait!  8', '2006-11-05 15:03:54.000000', NULL, 1),
