INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3022782, 422547, 65234, '<td valign="top">Certainly the most original title in the lot!  Bonus point for creativity.</td>', 'Certainly the most original title in the lot!  Bonus point for creativity.', '2006-11-11 23:00:07.000000', NULL, 1),
(3022784, 422292, 65234, '<td valign="top">Very punny ...</td>', 'Very punny ...', '2006-11-11 23:00:24.000000', NULL, 1),
(3022789, 422465, 22734, '<td valign="top">You are not even going to allow a little hint as to identity. Lol DPC voters do not show much mercy, but hey, I like the Magritte approach. Placing the focus on the fingers would have made this a stronger image. I know, it is difficult to self focus. One way to solve this problem is to get more light so that you would be forced to close down the lens giving you a more forgiving dof. Regardless, you get a score bump.</td>', 'You are not even going to allow a little hint as to identity. Lol DPC voters do not show much mercy, but hey, I like the Magritte approach. Placing the focus on the fingers would have made this a stronger image. I know, it is difficult to self focus. One way to solve this problem is to get more light so that you would be forced to close down the lens giving you a more forgiving dof. Regardless, you get a score bump.', '2006-11-11 23:03:53.000000', NULL, 1),
(3022793, 422322, 56744, '<td valign="top">Once upon a time there was a muts and a ball... and a 10 from me. Wonderful picture you have here. Photos like this one must appear in the first page. I wish the voters understand the quality inside of this piece of art.</td>', 'Once upon a time there was a muts and a ball... and a 10 from me. Wonderful picture you have here. Photos like this one must appear in the first page. I wish the voters understand the quality inside of this piece of art.', '2006-11-11 23:04:30.000000', NULL, 1),
(3022794, 422209, 65234, '<td valign="top">Put this away, and take it back out when your son brings home his first serious date.  I''m sure he''ll thank you ... creatively ;-)</td>', 'Put this away, and take it back out when your son brings home his first serious date.  I''m sure he''ll thank you ... creatively ;-)', '2006-11-11 23:05:17.000000', NULL, 1),
(3022795, 422729, 22734, '<td valign="top">I will not let you sit me on the couch. You are searching too deep. lol A bump for the intensity in your face.</td>', 'I will not let you sit me on the couch. You are searching too deep. lol A bump for the intensity in your face.', '2006-11-11 23:05:29.000000', NULL, 1),
(3022797, 422554, 22734, '<td valign="top">Interesting concept and very well framed. A sharper focus would have elevated this image. You still get credit for a good effort. Bump.</td>', 'Interesting concept and very well framed. A sharper focus would have elevated this image. You still get credit for a good effort. Bump.', '2006-11-11 23:06:32.000000', NULL, 1),
(3022800, 422633, 22734, '<td valign="top">I would have brought a rake and stood there looking overwhelmed. LOL Nice quiet position with attire that matches the foliage. Bump.</td>', 'I would have brought a rake and stood there looking overwhelmed. LOL Nice quiet position with attire that matches the foliage. Bump.', '2006-11-11 23:08:12.000000', NULL, 1),
